from itertools import permutations

def solve_qg3_order6():
    n = 6

    # Try using z3
    from z3 import Int, Solver, And, Or, Distinct, If, sat

    # Create variables
    x = [[Int(f'x_{i}_{j}') for j in range(n)] for i in range(n)]

    s = Solver()

    # Domain constraints
    for i in range(n):
        for j in range(n):
            s.add(x[i][j] >= 0, x[i][j] < n)

    # Latin square: each row is a permutation
    for i in range(n):
        s.add(Distinct(x[i]))

    # Latin square: each column is a permutation
    for j in range(n):
        s.add(Distinct([x[i][j] for i in range(n)]))

    # Idempotent: x[i][i] = i
    for i in range(n):
        s.add(x[i][i] == i)

    # QG3: x[x[i][j]][x[j][i]] = i
    # This requires nested indexing - use auxiliary variables or encoding
    # We'll use a select/store approach

    # For each pair (i,j), we need x[x[i][j]][x[j][i]] = i
    # Let a = x[i][j], b = x[j][i], then x[a][b] = i

    for i in range(n):
        for j in range(n):
            a = x[i][j]
            b = x[j][i]
            # x[a][b] = i
            # We need to express: for each possible value of a and b, x[a][b] = i
            for va in range(n):
                for vb in range(n):
                    s.add(If(And(a == va, b == vb), x[va][vb] == i, True))

    result = s.check()
    if result == sat:
        m = s.model()
        grid = []
        for i in range(n):
            for j in range(n):
                grid.append(m[x[i][j]].as_long())
        return grid
    else:
        return None

