def solve_backtrack():
    n = 6
    x = [[-1]*n for _ in range(n)]

    # Set diagonal
    for i in range(n):
        x[i][i] = i

    # We'll fill cell by cell in row-major order, skipping diagonal
    cells = [(i,j) for i in range(n) for j in range(n) if i != j]

    def is_valid(x, i, j, v):
        # Check row: v not already in row i
        if v in x[i]:
            return False
        # Check col: v not already in col j
        for r in range(n):
            if x[r][j] == v:
                return False
        return True

    def check_qg3_partial(x, i, j):
        # Check QG3 for all pairs where both x[i][j] and x[j][i] are set
        n = 6
        for ii in range(n):
            for jj in range(n):
                a = x[ii][jj]
                b = x[jj][ii]
                if a == -1 or b == -1:
                    continue
                if x[a][b] == -1:
                    continue
                if x[a][b] != ii:
                    return False
        return True

    def backtrack(idx):
        if idx == len(cells):
            return check_qg3_partial(x, -1, -1)

        i, j = cells[idx]
        for v in range(n):
            if is_valid(x, i, j, v):
                x[i][j] = v
                if check_qg3_partial(x, i, j):
                    if backtrack(idx + 1):
                        return True
                x[i][j] = -1
        return False

    if backtrack(0):
        return [x[i][j] for i in range(n) for j in range(n)]
    return None

